import React, { useState, useEffect } from 'react';
import { fetchResorts, fetchResort } from './api';

function App() {
  const [resorts, setResorts] = useState([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    const loadResorts = async () => {
      setLoading(true);
      try {
        const data = await fetchResorts();
        if (Array.isArray(data)) {
          setResorts(data);
        } else {
          console.error('Unexpected data format:', data);
          setError('Unexpected data format');
        }
      } catch (error) {
        console.error('Error loading resorts:', error);
        setError('Error loading resorts');
      } finally {
        setLoading(false);
      }
    };

    loadResorts();
  }, []);

  const handleSearch = async () => {
    setLoading(true);
    setError('');
    try {
      const resortData = await fetchResort(search);
      if (resortData) {
        setResorts([resortData]);
      } else {
        console.error('No data found for the given search term');
        setError('No data found');
      }
    } catch (error) {
      console.error('Error searching for resort:', error);
      setError('Error searching for resort');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <input
        type="text"
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />
      <button onClick={handleSearch}>Search</button>
      {loading && <p>Loading...</p>}
      {error && <p>{error}</p>}
      <ul>
        {resorts.length > 0 ? (
          resorts.map(resort => (
            <li key={resort.slug || 'unknown'}>
              {resort.name || 'Unknown Resort'}
            </li>
          ))
        ) : (
          <li>No resorts found</li>
        )}
      </ul>
    </div>
  );
}

export default App;
